    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSum1, uint minSum2, address log1) public {
        c.SetMinSum(minSum1); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool revertedMin;
        c.SetMinSum(minSum2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedMin = true;
        } else {
            revertedMin = false;
        }

        bool revertedLog;
        c.SetLogFile(log1); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedLog = true;
        } else {
            revertedLog = false;
        }

        assert(revertedMin && revertedLog && c.MinSum() == minBefore && c.MinSum() == minSum1);
    }

    receive() external payable {}
