pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum1, uint256 minSum2, address log1) internal {
        try c.SetMinSum(minSum1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool revertedMin;
        try c.SetMinSum(minSum2) {
            revertedMin = false;
        } catch {
            revertedMin = true;
        }
        bool revertedLog;
        try c.SetLogFile(log1) {
            revertedLog = false;
        } catch {
            revertedLog = true;
        }
        assertTrue(revertedMin && revertedLog && c.MinSum() == minBefore && c.MinSum() == minSum1);
    }

    function testFuzz_run(uint256 minSum1, uint256 minSum2, address log1) public {
        vm.assume(log1.code.length == 0 && uint160(log1) > 0xffff && log1 != address(this) && log1 != address(c) && log1 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && log1 != 0x000000000000000000636F6e736F6c652e6c6f67 && log1 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && log1 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(minSum1, minSum2, log1);
    }

    receive() external payable {}
}
